  'node.send-gmail.label': 'Enviar a través de Gmail',
  // Configuration des nodes — libellés de champs et aides (lot 21)
  // ⚠️ Schéma de clé DESCRIPTIF (`node.<type>.<champ>.label|help`). Les anciennes
  // clés `node.<type>.fN` restent en place — renuméroter aurait été risqué pour
  // zéro gain. Toute clé AJOUTÉE suit le schéma descriptif : opaque = collisions.
  'node.compare-catalog.urlColumn.help': 'Enlace de la ficha de producto en SU sitio — hace que el nombre sea clicable en la tabla para comprobar el precio. Opcional.',
  'node.compare-catalog.watchId.help': 'Dejar VACÍO: el seguimiento es automáticamente el del flujo de trabajo (el mismo que «Cosecha de competidores» del flujo de trabajo). Rellenar solo para compartir un seguimiento entre varios flujos de trabajo.',
  'node.compare-prices.noSource.help': 'Modo «familia»: conectar todas las marcas a «competidores». 1 línea por producto, 1 columna de precio por marca, mejor precio + diferencia.',
  'node.cron.afterEnd.help': 'Ideal para un scraping que avanza por tramos: la siguiente ejecución comienza «Cada X» DESPUÉS del final de la anterior, sin cadencia fija — ni solapamiento, ni tiempo muerto. La hora y el día a continuación se ignoran en este modo.',
  'node.directed-search.genericSites.help': 'Amazon, Cdiscount, Kramp…: búsqueda web por ref. + Firecrawl (renderizado JS + anti-bot). Requiere una clave Firecrawl. Coste por ref. — empezar por 1 sitio para validar.',
  'node.directed-search.descriptionColumn.help': 'Ej.: TEXT_VENTE_FR. DECISIVO en un catálogo de piezas adaptables: si su referencia de artículo es un código INTERNO, ningún competidor la tiene — solo las ref. de origen citadas aquí («Origen: …») permiten encontrar el producto.',
  'node.directed-search.productBudget.help': "Número de productos probados por ejecución. Cada uno se busca en todos los sitios activos. La pasada se detiene sola al vencer el plazo de la ejecución y se reanuda en el producto siguiente: un presupuesto amplio ya no hace perder trabajo, solo ocupa toda la ventana. La concurrencia se adapta al número de sitios (8 solicitudes simultáneas en total). ⚠ Cada producto cuesta 1 o 2 solicitudes POR SITIO: en un motor de pago como Firecrawl, vigile los créditos.",
  'node.directed-search.watchId.help': 'Dejar VACÍO: el seguimiento es el del flujo de trabajo (compartido con «Comparar catálogo» del mismo flujo de trabajo — los precios encontrados suben entonces al dashboard).',
  'node.harvest-competitor.pageBudget.help': 'Páginas de lista cosechadas en cada ejecución, compartidas entre los sitios. Un sitio puede RESERVAR su propio presupuesto (campo «páginas» de su tarjeta en «Sitios de origen») — útil para limitar un competidor de pago sin racionar los gratuitos. ⚠ Es EL techo de rendimiento. En una ejecución PLANIFICADA (cron), la ventana de tiempo limita ahora la pasada por sí misma: este campo ya no es más que un techo de seguridad, sea generoso. En una ejecución lanzada desde el navegador, no hay plazo — es este el que decide la duración.',
  'node.save-pim.sourceId.help': 'ID de la fuente. Si no existe en el proyecto, los productos se crearán pero serán invisibles en la lista de fuentes (a corregir en la fase 2).',
  'node.price-watch.thresholdPct.label': 'Umbral de variación (%)',
  'node.price-watch.thresholdPct.help': '0 = señalar cualquier cambio.',
  'node.price-watch.watchId.help': 'El estado (últimos precios vistos) se memoriza por identificador — un seguimiento por lista vigilada.',
  'node.price-watch.watchId.label': 'Identificador del seguimiento',
  'node.price-watch.keyColumn.label': 'Columna clave',
  'node.price-watch.keyColumn.help': 'Identifica cada producto entre dos ejecuciones (url, sku, ean…).',
  'node.price-watch.valueColumn.label': 'Columna precio',
  'node.price-watch.valueColumn.help': 'Valor supervisado (analiza « 1 299,90 € »).',
  'node.price-watch-track.nameColumn.label': 'Columna Nombre',
  'node.price-watch-track.nameColumn.help': 'Columna del nombre del producto en la hoja de entrada.',
  'node.price-watch-track.watchId.label': 'Identificador de seguimiento',
  'node.price-watch-track.watchId.help': 'Memoriza las URL fijadas y el historial entre dos ejecuciones.',
  'node.harvest-competitor.families.label': 'Familias objetivo (separadas por comas)',
  'node.harvest-competitor.watchId.label': 'Identificador de seguimiento (avanzado)',
