  'node.harvest-competitor.f1': 'Un dominio por línea. Ej.: «pro-motoculture.com». PrestaShop soportado de forma nativa. IGNORADO si un nodo «Sitios de origen» está conectado en el puerto de sitios.',
  'node.harvest-competitor.f2': 'proporcionado por «Sitios de origen»',
  'node.harvest-competitor.f3': 'Dejar VACÍO si se conecta la hoja de origen en el puerto «products»: las familias se leen entonces en la columna a continuación, siempre actualizada. Rellenar para FORZAR una segmentación precisa («CORREAS, FILTRACIÓN»). Vacío y sin hoja = catálogo completo.',
  'node.harvest-competitor.f4': 'Ej.: Familia. Utilizada cuando la hoja de origen está conectada: se extraen las familias distintas, luego una IA empareja SU vocabulario con el del competidor («CORREAS» encuentra su sección «transmisión»). Sin IA disponible, se escanea el catálogo completo — nunca menos.',
  'node.harvest-competitor.f5': 'Dejar VACÍO: el seguimiento es automáticamente el del workflow (compartido con «Comparar catálogo» del mismo workflow). Rellenar solo para compartir un mismo seguimiento entre varios workflows.',
  'node.harvest-competitor.f6': 'proporcionado por «Sitios de origen»',
  'node.list-products.f1': 'URLs de páginas de lista (o DOMINIOS si «Familia» está rellenado)',
