  'node.list-products.f10': 'Enriquecer cada ficha (EAN, marca, precio)',
  'node.list-products.f11': 'Busca en CADA ficha de producto el EAN/marca/precio canónicos (JSON-LD, cascada Jina→Firecrawl→Bright Data). Más completo pero 1 petición por producto (más lento).',
  'node.list-products.f12': 'Marca (filtro)',
