  'pw.title': 'Vigilancia de precios',
  'pw.noPending': 'Ningún emparejamiento por confirmar por el momento. Las coincidencias dudosas (por nombre, cuando no hay ni EAN ni referencia común) aparecerán aquí para su validación.',
  'pw.kpi.priceHold': 'Mantenimiento de precio',
  'pw.kpi.exposed': 'Expuestos',
  'pw.kpi.index': 'Índice de tarifa',
  'pw.kpi.index.sub': 'base 100 = mediana del mercado',
  'pw.kpi.index.title': 'Índice TARIFA base 100: su precio en relación con el precio mediano de los competidores emparejados, mediana sobre todo el catálogo.\n100 = está al nivel del mercado · 105 = 5 % por encima · 95 = 5 % por debajo.\n\nCalculado sobre el catálogo COMPLETO (no sobre la muestra limitada): a diferencia de la diferencia mediana, no deriva cuando el informe se trunca.\n\nDado que sus precios de origen son tarifas SIN DESCUENTO, es un índice de posicionamiento de catálogo — no un índice neto de cliente.',
  'pw.kpi.index.stale': 'Informe anterior a este indicador: valor recalculado sobre la muestra limitada. Iniciar un análisis para el índice exacto.',
  'pw.kpi.gap': 'Diferencia unitaria acumulada',
  'pw.kpi.gap.sub': 'Σ por unidad · {median} med.',
  'pw.kpi.gap.title': 'Suma, en los productos infravalorados, de la diferencia UNITARIA entre su precio y el mejor precio de la competencia.\n\n⚠ NO es un importe de volumen de negocio: sin volumen de ventas, 3 € en una pieza vendida 4 veces al año pesan tanto como 3 € en una pieza vendida 8000 veces. Debe leerse como una medida de magnitud, no de impacto.\n\nSubtítulo: diferencia mediana en los pares producto × competidor',
  'pw.kpi.gap.truncated': '(muestra limitada).',
