  'sc.search.introFull': 'Búsqueda → Describir qué se busca y dónde («cortacéspedes Honda en LeroyMerlin y Castorama»). La IA interpreta la solicitud, consulta cada sitio indicado, se selecciona, y cada página es extraída con el motor Scrape / Producto completo.',
  'st.vendorPrompt.placeholder': 'Prompt global aplicado a todos los productos de este proveedor.\nEjemplos:\n• «Retirar siempre el encabezado H1 de la descripción.»\n• «Las especificaciones están en los acordeones, no en la tabla principal.»\n• «Ignorar las filas ’CARTON A/B/C’ en las variantes.»',
  'st.sharedPrompt.placeholder': 'Prompt aplicado a TODAS las plantillas de este proveedor (compartido).\nEjemplos:\n• «Los precios incluyen IVA en este proveedor, no convertir.»\n• «Las imágenes de producto están en /media/catalog/, ignorar las demás.»\n• «La marca es siempre la misma: escribir ’Milwaukee’.»',
  'st.fieldPrompt.placeholder': 'Instrucciones de extracción para este campo (ej.: «Retirar el encabezado, conservar solo los párrafos.», «Ignorar los precios.», «Traducir al español.»)',
  'st.degradedRenderFull': 'Renderizado degradado esperado — las fuentes personalizadas y los iconos webfont no cargan (CORS en @font-face). Doble clic para capturar un elemento, un solo clic para navegar (acordeones, pestañas).',
